//! v3 reader fixtures for positioned-model tests (`test-api`).
//!
//! Fixtures live in `context-read/tests/fixtures/v3` (authoritative manifest
//! `scenarios.json`, generated by the `ngrams` oracle); they are read from
//! disk so model and navigation tests need no dependency on `ngrams` or
//! `legacy`.

use std::path::PathBuf;

use serde::Deserialize;

use super::{
    PositionedGraph,
    interchange::PositionedGraphSnapshot,
};
use crate::BaseGraphKind;

#[derive(Deserialize)]
struct Scenario {
    name: String,
}

/// Directory of the v3 fixtures.
pub fn v3_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../context-read/tests/fixtures/v3")
}

fn read(path: PathBuf) -> Vec<u8> {
    std::fs::read(&path).unwrap_or_else(|error| panic!("{}: {error}", path.display()))
}

/// Every manifest fixture as `(name, snapshot)`, decoded and structurally
/// validated. Panics on any I/O, decoding or validation error.
pub fn v3_fixtures() -> Vec<(String, PositionedGraphSnapshot)> {
    let scenarios: Vec<Scenario> =
        serde_json::from_slice(&read(v3_dir().join("scenarios.json"))).unwrap();
    assert!(!scenarios.is_empty());
    scenarios
        .into_iter()
        .map(|Scenario { name }| {
            let fixture: PositionedGraphSnapshot =
                serde_json::from_slice(&read(v3_dir().join(format!("{name}.json"))))
                    .unwrap_or_else(|error| panic!("{name}: {error}"));
            fixture
                .validate()
                .unwrap_or_else(|error| panic!("{name}: {error}"));
            (name, fixture)
        })
        .collect()
}

/// Every manifest fixture as `(name, graph)`, converted with
/// [`PositionedGraph::from_interchange`].
pub fn v3_graphs() -> Vec<(String, PositionedGraph<BaseGraphKind>)> {
    v3_fixtures()
        .into_iter()
        .map(|(name, fixture)| {
            let graph = PositionedGraph::from_interchange(&fixture.graph)
                .unwrap_or_else(|error| panic!("{name}: {error}"));
            (name, graph)
        })
        .collect()
}
